{
  "findings": [
    {
      "check_id": "CKV_GCP_32",
      "title": "Ensure 'Block Project-wide SSH keys' is enabled for VM instances",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Project-wide SSH keys can allow unintended access to the VM instance. Disabling them ensures only explicitly defined SSH keys are used."
    },
    {
      "check_id": "CKV_GCP_38",
      "title": "Ensure VM disks for critical VMs are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Using Customer Supplied Encryption Keys (CSEK) provides greater control over disk encryption and ensures data security."
    },
    {
      "check_id": "CKV_GCP_30",
      "title": "Ensure that instances are not configured to use the default service account",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Using the default service account can lead to over-privileged access. A custom service account with least privilege should be used."
    },
    {
      "check_id": "CKV_GCP_31",
      "title": "Ensure that instances are not configured to use the default service account with full access to all Cloud APIs",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Granting full access to all Cloud APIs can lead to excessive permissions. Scopes should be restricted to the minimum required."
    },
    {
      "check_id": "CKV_GCP_40",
      "title": "Ensure that Compute instances do not have public IP addresses",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Public IP addresses expose the instance to the internet, increasing the attack surface. Private IPs should be used instead."
    },
    {
      "check_id": "CKV_GCP_35",
      "title": "Ensure 'Enable connecting to serial ports' is not enabled for VM Instance",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Enabling serial port access can expose the instance to unauthorized access. It should be disabled unless explicitly required."
    },
    {
      "check_id": "CKV_GCP_39",
      "title": "Ensure Compute instances are launched with Shielded VM enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Shielded VM provides enhanced security features such as secure boot and integrity monitoring, protecting against rootkits and bootkits."
    }
  ],
  "patched_code": "resource \"google_compute_instance\" \"backup_orchestration_engine\" {\n  name         = \"enterprise-disaster-recovery-orchestration-platform-compute-orchestration\"\n  machine_type = \"e2-medium\"\n  zone         = \"${var.primary_region}-a\"\n  boot_disk {\n    initialize_params {\n      image = \"debian-cloud/debian-11\"\n      size  = 50\n    }\n    disk_encryption_key {\n      kms_key_self_link = var.csek_kms_key_self_link\n    }\n  }\n  network_interface {\n    network    = google_compute_network.dr_vpc.id\n    subnetwork = google_compute_subnetwork.management_subnet.id\n  }\n  service_account {\n    email  = var.custom_service_account_email\n    scopes = [\"https://www.googleapis.com/auth/compute.readonly\"]\n  }\n  metadata = {\n    block-project-ssh-keys = true\n    serial-port-enable     = false\n    startup-script         = file(\"${path.module}/scripts/orchestration-startup.sh\")\n  }\n  tags = [\"dr-internal\", \"orchestration-engine\"]\n  shielded_instance_config {\n    enable_secure_boot          = true\n    enable_vtpm                 = true\n    enable_integrity_monitoring = true\n  }\n  depends_on = [\n    google_storage_bucket.primary_backup_storage,\n    google_sql_database_instance.recovery_database\n  ]\n}",
  "fix_summary": "The following changes were made: disabled project-wide SSH keys, enforced CSEK for disk encryption, replaced the default service account with a custom one, restricted API scopes, removed the public IP address, disabled serial port access, and enabled Shielded VM features."
}
